mc("ex.q1", ("निम्न में से कौन-सा पदार्थ लेंस बनाने के लिए प्रयुक्त नहीं किया जा सकता?", "નીચેનામાંથી કયો પદાર્થ લેન્સ બનાવવા વાપરી શકાય નહિ?"), ("लेंस पारदर्शी होना चाहिए; मिट्टी अपारदर्शी है।", "લેન્સ પારદર્શક હોવો જોઈએ; માટી અપારદર્શક છે."),
   {"Water": (("जल", "પાણી"), ("जल पारदर्शी है; पानी की बूँद लेंस की तरह काम करती है।", "પાણી પારદર્શક છે; પાણીનું ટીપું લેન્સની જેમ કામ કરે છે.")), "Glass": (("काँच", "કાચ"), ("काँच सामान्य लेंस पदार्थ है।", "કાચ લેન્સનો સામાન્ય પદાર્થ છે.")),
    "Plastic": (("प्लास्टिक", "પ્લાસ્ટિક"), ("पारदर्शी प्लास्टिक से लेंस बनते हैं।", "પારદર્શક પ્લાસ્ટિકમાંથી લેન્સ બને છે.")), "Clay": (("मिट्टी", "માટી"), OK)})
mc("ex.q2", ("किसी अवतल दर्पण से प्राप्त प्रतिबिंब आभासी, सीधा तथा बिंब से बड़ा पाया गया। वस्तु की स्थिति कहाँ होनी चाहिए?", "કોઈ અંતર્ગોળ અરીસાથી મળેલું પ્રતિબિંબ આભાસી, સીધું અને વસ્તુ કરતાં મોટું જોવા મળ્યું. વસ્તુનું સ્થાન ક્યાં હોવું જોઈએ?"),
   ("केवल P और F के बीच रखा बिंब आभासी, सीधा, बड़ा प्रतिबिंब देता है।", "ફક્ત P અને F ની વચ્ચે મૂકેલી વસ્તુ આભાસી, સીધું, મોટું પ્રતિબિંબ આપે છે."),
   {"Between the principal focus and the centre of curvature": (("मुख्य फ़ोकस तथा वक्रता केंद्र के बीच", "મુખ્ય કેન્દ્ર અને વક્રતાકેન્દ્રની વચ્ચે"), ("इससे वास्तविक, बड़ा, उलटा प्रतिबिंब बनता है।", "તેનાથી વાસ્તવિક, મોટું, ઊલટું પ્રતિબિંબ મળે છે.")),
    "At the centre of curvature": (("वक्रता केंद्र पर", "વક્રતાકેન્દ્ર પર"), ("इससे समान साइज़ का वास्तविक प्रतिबिंब बनता है।", "તેનાથી સમાન કદનું વાસ્તવિક પ્રતિબિંબ મળે છે.")),
    "Beyond the centre of curvature": (("वक्रता केंद्र से परे", "વક્રતાકેન્દ્રની પેલે પાર"), ("इससे छोटा वास्तविक प्रतिबिंब बनता है।", "તેનાથી નાનું વાસ્તવિક પ્રતિબિંબ મળે છે.")),
    "Between the pole of the mirror and its principal focus.": (("दर्पण के ध्रुव तथा मुख्य फ़ोकस के बीच", "અરીસાના ધ્રુવ અને મુખ્ય કેન્દ્રની વચ્ચે"), OK)})
mc("ex.q3", ("किसी बिंब का वास्तविक तथा समान साइज़ का प्रतिबिंब प्राप्त करने के लिए बिंब को उत्तल लेंस के सामने कहाँ रखें?", "કોઈ વસ્તુનું વાસ્તવિક અને સમાન કદનું પ્રતિબિંબ મેળવવા વસ્તુને બહિર્ગોળ લેન્સની સામે ક્યાં મૂકવી?"), ("2F₁ पर रखने से प्रतिबिंब 2F₂ पर, वास्तविक और समान साइज़ का बनता है।", "2F₁ પર મૂકવાથી પ્રતિબિંબ 2F₂ પર, વાસ્તવિક અને સમાન કદનું મળે છે."),
   {"At the principal focus of the lens": (("लेंस के मुख्य फ़ोकस पर", "લેન્સના મુખ્ય કેન્દ્ર પર"), ("प्रतिबिंब अनंत पर बनेगा।", "પ્રતિબિંબ અનંત અંતરે મળશે.")), "At twice the focal length": (("फ़ोकस दूरी की दुगुनी दूरी पर", "કેન્દ્રલંબાઈથી બમણા અંતરે"), OK),
    "At infinity": (("अनंत पर", "અનંત અંતરે"), ("प्रतिबिंब F₂ पर एक बिंदु होगा।", "પ્રતિબિંબ F₂ પર એક બિંદુ હશે.")),
    "Between the optical centre of the lens and its principal focus.": (("लेंस के प्रकाशिक केंद्र तथा मुख्य फ़ोकस के बीच", "લેન્સના પ્રકાશીય કેન્દ્ર અને મુખ્ય કેન્દ્રની વચ્ચે"), ("इससे आभासी प्रतिबिंब बनता है।", "તેનાથી આભાસી પ્રતિબિંબ મળે છે."))})
mc("ex.q4", ("किसी गोलीय दर्पण तथा किसी पतले गोलीय लेंस दोनों की फ़ोकस दूरियाँ –15 cm हैं। दर्पण तथा लेंस संभवतः हैं", "કોઈ ગોળીય અરીસો અને કોઈ પાતળો ગોળીય લેન્સ બંનેની કેન્દ્રલંબાઈ –15 cm છે. અરીસો અને લેન્સ કદાચ છે"),
   ("ऋणात्मक फ़ोकस दूरी का अर्थ अवतल दर्पण और अवतल लेंस है।", "ઋણ કેન્દ્રલંબાઈ એટલે અંતર્ગોળ અરીસો અને અંતર્ગોળ લેન્સ."),
   {"both concave.": (("दोनों अवतल", "બંને અંતર્ગોળ"), OK), "both convex.": (("दोनों उत्तल", "બંને બહિર્ગોળ"), ("उत्तल दर्पण और उत्तल लेंस दोनों की फ़ोकस दूरी धनात्मक होती है।", "બહિર્ગોળ અરીસો અને બહિર્ગોળ લેન્સ બંનેની કેન્દ્રલંબાઈ ધન હોય છે.")),
    "the mirror is concave and the lens is convex.": (("दर्पण अवतल तथा लेंस उत्तल", "અરીસો અંતર્ગોળ અને લેન્સ બહિર્ગોળ"), ("उत्तल लेंस की f धनात्मक होती है।", "બહિર્ગોળ લેન્સનો f ધન હોય છે.")),
    "the mirror is convex, but the lens is concave.": (("दर्पण उत्तल तथा लेंस अवतल", "અરીસો બહિર્ગોળ અને લેન્સ અંતર્ગોળ"), ("उत्तल दर्पण की f धनात्मक होती है।", "બહિર્ગોળ અરીસાનો f ધન હોય છે."))})
MIR5 = {"only plane.": ("केवल समतल", "ફક્ત સમતલ"), "only concave.": ("केवल अवतल", "ફક્ત અંતર્ગોળ"), "only convex.": ("केवल उत्तल", "ફક્ત બહિર્ગોળ"), "either plane or convex.": ("या तो समतल अथवा उत्तल", "સમતલ અથવા બહિર્ગોળ")}
FB5 = {"only plane.": ("उत्तल दर्पण भी सदा सीधा प्रतिबिंब देता है।", "બહિર્ગોળ અરીસો પણ હંમેશાં સીધું પ્રતિબિંબ આપે છે."), "only concave.": ("अवतल दर्पण से दूर होने पर प्रतिबिंब उलटा होता है।", "અંતર્ગોળ અરીસાથી દૂર હોઈએ ત્યારે પ્રતિબિંબ ઊલટું હોય છે."),
       "only convex.": ("समतल दर्पण भी सदा सीधा प्रतिबिंब देता है।", "સમતલ અરીસો પણ હંમેશાં સીધું પ્રતિબિંબ આપે છે."), "either plane or convex.": OK}
mc("ex.q5", ("आप किसी दर्पण से कितनी ही दूरी पर खड़े हों, आपका प्रतिबिंब सदैव सीधा प्रतीत होता है। संभवतः दर्पण है", "તમે અરીસાથી ગમે તેટલા અંતરે ઊભા હો, તમારું પ્રતિબિંબ હંમેશાં સીધું દેખાય છે. અરીસો કદાચ છે"),
   ("समतल और उत्तल दर्पण सदा सीधे प्रतिबिंब देते हैं; अवतल दर्पण से दूर होने पर प्रतिबिंब उलटा होता है।", "સમતલ અને બહિર્ગોળ અરીસા હંમેશાં સીધાં પ્રતિબિંબ આપે છે; અંતર્ગોળ અરીસાથી દૂર હોઈએ ત્યારે પ્રતિબિંબ ઊલટું હોય છે."),
   {k: (MIR5[k], FB5[k]) for k in MIR5})
mc("ex.q6", ("किसी शब्दकोश में पाए गए छोटे अक्षरों को पढ़ते समय आप निम्न में से कौन-सा लेंस पसंद करेंगे?", "શબ્દકોશમાં આવેલા નાના અક્ષરો વાંચતી વખતે તમે નીચેનામાંથી કયો લેન્સ પસંદ કરશો?"), ("कम फ़ोकस दूरी का उत्तल लेंस बड़ा, आभासी, सीधा प्रतिबिंब देता है: आवर्धक लेंस।", "ઓછી કેન્દ્રલંબાઈનો બહિર્ગોળ લેન્સ મોટું, આભાસી, સીધું પ્રતિબિંબ આપે છે: બિલોરી કાચ."),
   {"A convex lens of focal length 50 cm.": (("50 cm फ़ोकस दूरी का एक उत्तल लेंस", "50 cm કેન્દ્રલંબાઈનો એક બહિર્ગોળ લેન્સ"), ("अधिक फ़ोकस दूरी कम आवर्धन देती है।", "વધુ કેન્દ્રલંબાઈ ઓછી મોટવણી આપે છે.")),
    "A concave lens of focal length 50 cm.": (("50 cm फ़ोकस दूरी का एक अवतल लेंस", "50 cm કેન્દ્રલંબાઈનો એક અંતર્ગોળ લેન્સ"), ("अवतल लेंस अक्षरों को छोटा करता है।", "અંતર્ગોળ લેન્સ અક્ષરોને નાના કરે છે.")),
    "A convex lens of focal length 5 cm.": (("5 cm फ़ोकस दूरी का एक उत्तल लेंस", "5 cm કેન્દ્રલંબાઈનો એક બહિર્ગોળ લેન્સ"), OK),
    "A concave lens of focal length 5 cm.": (("5 cm फ़ोकस दूरी का एक अवतल लेंस", "5 cm કેન્દ્રલંબાઈનો એક અંતર્ગોળ લેન્સ"), ("अवतल लेंस अक्षरों को छोटा करता है।", "અંતર્ગોળ લેન્સ અક્ષરોને નાના કરે છે."))})
add("ex.q7", ("15 cm फ़ोकस दूरी के एक अवतल दर्पण का उपयोग करके हम किसी बिंब का सीधा प्रतिबिंब बनाना चाहते हैं। बिंब का दर्पण से दूरी का परिसर (range) क्या होना चाहिए? प्रतिबिंब की प्रकृति कैसी है? प्रतिबिंब बिंब से बड़ा है अथवा छोटा? इस स्थिति में प्रतिबिंब बनने का एक किरण आरेख बनाइए।",
              "15 cm કેન્દ્રલંબાઈવાળા અંતર્ગોળ અરીસાનો ઉપયોગ કરીને આપણે કોઈ વસ્તુનું સીધું પ્રતિબિંબ મેળવવા માગીએ છીએ. વસ્તુનું અરીસાથી અંતર કયા ગાળામાં હોવું જોઈએ? પ્રતિબિંબનો પ્રકાર કેવો છે? પ્રતિબિંબ વસ્તુ કરતાં મોટું છે કે નાનું? આ સ્થિતિમાં પ્રતિબિંબ-રચનાની કિરણાકૃતિ દોરો."),
    {0: ("बिंब ध्रुव और फ़ोकस के बीच होना चाहिए: दर्पण से 15 cm से कम दूरी पर।", "વસ્તુ ધ્રુવ અને મુખ્ય કેન્દ્રની વચ્ચે હોવી જોઈએ: અરીસાથી 15 cm કરતાં ઓછા અંતરે."), 1: ("प्रतिबिंब आभासी और सीधा है, दर्पण के पीछे बनता है, और बिंब से बड़ा है।", "પ્રતિબિંબ આભાસી અને સીધું છે, અરીસાની પાછળ બને છે, અને વસ્તુ કરતાં મોટું છે."),
     2: ("किरण आरेख: अक्ष के समांतर किरण F से होकर परावर्तित होती है, और ध्रुव की ओर जाती किरण सममित रूप से परावर्तित होती है; परावर्तित किरणें फैलती हैं, और उनके पीछे की ओर बढ़ाए गए भाग दर्पण के पीछे मिलकर बड़ा, सीधा प्रतिबिंब बनाते हैं।",
         "કિરણાકૃતિ: અક્ષને સમાંતર કિરણ F માંથી પસાર થઈ પરાવર્તિત થાય છે, અને ધ્રુવ તરફ જતું કિરણ સમમિત રીતે પરાવર્તિત થાય છે; પરાવર્તિત કિરણો ફેલાય છે, અને તેમના પાછળ લંબાવેલા ભાગ અરીસાની પાછળ મળીને મોટું, સીધું પ્રતિબિંબ બનાવે છે.")})
add("ex.q8", ("निम्न स्थितियों में प्रयुक्त दर्पण का प्रकार बताइए।\n\n(a) किसी कार का अग्र-दीप (हेड-लाइट)।\n\n(b) किसी वाहन का पार्श्व/पश्च-दृश्य दर्पण।\n\n(c) सौर भट्टी।\n\nअपने उत्तर की कारण सहित पुष्टि कीजिए।",
              "નીચેની પરિસ્થિતિઓમાં વપરાતા અરીસાનો પ્રકાર જણાવો.\n\n(a) કારની હેડલાઇટ.\n\n(b) વાહનનો બાજુનો/પાછળનું દૃશ્ય જોવાનો અરીસો.\n\n(c) સૌર-ભઠ્ઠી.\n\nતમારા જવાબનું કારણ આપો."),
    {0: ("(a) अवतल दर्पण: बल्ब उसके फ़ोकस पर होने से यह प्रकाश का प्रबल समांतर किरण-पुंज भेजता है।", "(a) અંતર્ગોળ અરીસો: બલ્બ તેના મુખ્ય કેન્દ્ર પર હોવાથી તે પ્રકાશનો પ્રબળ સમાંતર કિરણપુંજ મોકલે છે."), 1: ("(b) उत्तल दर्पण: यह सदा सीधा प्रतिबिंब देता है और इसका दृष्टि-क्षेत्र अधिक विस्तृत है।", "(b) બહિર્ગોળ અરીસો: તે હંમેશાં સીધું પ્રતિબિંબ આપે છે અને તેનું દૃષ્ટિક્ષેત્ર વધુ વિશાળ છે."),
     2: ("(c) अवतल दर्पण: यह सूर्य के प्रकाश को अपने फ़ोकस पर केंद्रित करके बहुत ऊष्मा उत्पन्न करता है।", "(c) અંતર્ગોળ અરીસો: તે સૂર્યપ્રકાશને પોતાના મુખ્ય કેન્દ્ર પર કેન્દ્રિત કરી ઘણી ઉષ્મા ઉત્પન્ન કરે છે.")})
add("ex.q9", ("किसी उत्तल लेंस का आधा भाग काले कागज़ से ढक दिया गया है। क्या यह लेंस किसी बिंब का पूरा प्रतिबिंब बना पाएगा? अपने उत्तर की प्रयोग द्वारा जाँच कीजिए। अपने प्रेक्षणों की व्याख्या कीजिए।", "બહિર્ગોળ લેન્સનો અડધો ભાગ કાળા કાગળથી ઢાંકી દીધો છે. શું આ લેન્સ વસ્તુનું પૂરું પ્રતિબિંબ બનાવશે? તમારા જવાબની પ્રયોગ દ્વારા ચકાસણી કરો. તમારાં અવલોકનો સમજાવો."),
    {0: ("हाँ, लेंस फिर भी पूरा प्रतिबिंब बनाता है।", "હા, લેન્સ તો પણ પૂરું પ્રતિબિંબ બનાવે છે."), 1: ("प्रयोग: उत्तल लेंस से मोमबत्ती की लौ का प्रतिबिंब परदे पर बनाइए, फिर लेंस का आधा भाग काले कागज़ से ढकिए; परदे पर पूरा प्रतिबिंब बना रहता है।", "પ્રયોગ: બહિર્ગોળ લેન્સ વડે મીણબત્તીની જ્યોતનું પ્રતિબિંબ પડદા પર મેળવો, પછી લેન્સનો અડધો ભાગ કાળા કાગળથી ઢાંકો; પડદા પર પૂરું પ્રતિબિંબ રહે છે."),
     2: ("लेंस के हर भाग पर बिंब के हर बिंदु से किरणें आती हैं, इसलिए खुला आधा भाग भी पूरा प्रतिबिंब बनाता है; केवल उसकी चमक कम हो जाती है।", "લેન્સના દરેક ભાગ પર વસ્તુના દરેક બિંદુથી કિરણો આવે છે, તેથી ખુલ્લો અડધો ભાગ પણ પૂરું પ્રતિબિંબ બનાવે છે; ફક્ત તેની તેજસ્વિતા ઓછી થાય છે.")})
add("ex.q10", ("5 cm लंबा कोई बिंब 10 cm फ़ोकस दूरी के किसी अभिसारी लेंस से 25 cm दूरी पर रखा जाता है। प्रकाश किरण आरेख खींचकर बनने वाले प्रतिबिंब की स्थिति, साइज़ तथा प्रकृति ज्ञात कीजिए।", "5 cm લાંબી એક વસ્તુ 10 cm કેન્દ્રલંબાઈવાળા અભિસારી લેન્સથી 25 cm અંતરે મૂકી છે. કિરણાકૃતિ દોરીને મળતા પ્રતિબિંબનું સ્થાન, કદ અને પ્રકાર શોધો."),
    {1: ("{0}, अतः {1} cm", "{0}, તેથી {1} cm"), 4: ("प्रतिबिंब लेंस के दूसरी ओर लगभग 16.7 cm पर, वास्तविक, उलटा और छोटा (3.3 cm ऊँचा) है। किरण आरेख: बिंब 2F₁ से परे, प्रतिबिंब F₂ और 2F₂ के बीच।", "પ્રતિબિંબ લેન્સની બીજી બાજુ આશરે 16.7 cm અંતરે, વાસ્તવિક, ઊલટું અને નાનું (3.3 cm ઊંચું) છે. કિરણાકૃતિ: વસ્તુ 2F₁ ની પેલે પાર, પ્રતિબિંબ F₂ અને 2F₂ ની વચ્ચે.")})
add("ex.q11", ("15 cm फ़ोकस दूरी का कोई अवतल लेंस किसी बिंब का प्रतिबिंब लेंस से 10 cm दूरी पर बनाता है। बिंब लेंस से कितनी दूरी पर स्थित है? किरण आरेख खींचिए।", "15 cm કેન્દ્રલંબાઈનો અંતર્ગોળ લેન્સ વસ્તુનું પ્રતિબિંબ લેન્સથી 10 cm અંતરે બનાવે છે. વસ્તુ લેન્સથી કેટલા અંતરે છે? કિરણાકૃતિ દોરો."),
    {0: ("{0} cm; अवतल लेंस का प्रतिबिंब आभासी, उसी ओर होता है: {1} cm", "{0} cm; અંતર્ગોળ લેન્સનું પ્રતિબિંબ આભાસી, એ જ બાજુ હોય છે: {1} cm"),
     2: ("{0} cm: बिंब लेंस के सामने 30 cm पर है। (किरण आरेख: प्रतिबिंब आभासी, सीधा और छोटा है, F₁ और O के बीच।)", "{0} cm: વસ્તુ લેન્સની સામે 30 cm અંતરે છે. (કિરણાકૃતિ: પ્રતિબિંબ આભાસી, સીધું અને નાનું છે, F₁ અને O ની વચ્ચે.)")})
add("ex.q12", ("15 cm फ़ोकस दूरी के किसी उत्तल दर्पण से कोई बिंब 10 cm दूरी पर रखा है। प्रतिबिंब की स्थिति तथा प्रकृति ज्ञात कीजिए।", "15 cm કેન્દ્રલંબાઈના બહિર્ગોળ અરીસાથી 10 cm અંતરે એક વસ્તુ મૂકી છે. પ્રતિબિંબનું સ્થાન અને પ્રકાર શોધો."),
    {1: SO, 2: ("प्रतिबिंब दर्पण के पीछे 6 cm पर, आभासी और सीधा है; {0}, अतः यह छोटा है।", "પ્રતિબિંબ અરીસાની પાછળ 6 cm અંતરે, આભાસી અને સીધું છે; {0}, તેથી તે નાનું છે.")})
add("ex.q13", ("एक समतल दर्पण द्वारा उत्पन्न आवर्धन +1 है। इसका क्या अर्थ है?", "સમતલ અરીસા વડે મળતી મોટવણી +1 છે. તેનો શો અર્થ છે?"),
    {0: ("|m| = 1: प्रतिबिंब बिंब के समान साइज़ का है।", "|m| = 1: પ્રતિબિંબ વસ્તુ જેટલા જ કદનું છે."), 1: ("+ चिह्न का अर्थ है कि प्रतिबिंब आभासी और सीधा है।", "+ સંજ્ઞાનો અર્થ છે કે પ્રતિબિંબ આભાસી અને સીધું છે.")})
add("ex.q14", ("5.0 cm लंबाई का कोई बिंब 30 cm वक्रता त्रिज्या के किसी उत्तल दर्पण के सामने 20 cm दूरी पर रखा गया है। प्रतिबिंब की स्थिति, प्रकृति तथा साइज़ ज्ञात कीजिए।", "5.0 cm લંબાઈની એક વસ્તુ 30 cm વક્રતાત્રિજ્યાના બહિર્ગોળ અરીસાની સામે 20 cm અંતરે મૂકી છે. પ્રતિબિંબનું સ્થાન, પ્રકાર અને કદ શોધો."),
    {1: ("{0}, अतः {1} cm दर्पण के पीछे", "{0}, તેથી {1} cm અરીસાની પાછળ"), 2: ("{0}, {1} cm: आभासी, सीधा और छोटा।", "{0}, {1} cm: આભાસી, સીધું અને નાનું.")})
add("ex.q15", ("7.0 cm साइज़ का कोई बिंब 18 cm फ़ोकस दूरी के किसी अवतल दर्पण के सामने 27 cm दूरी पर रखा गया है। दर्पण से कितनी दूरी पर किसी परदे को रखें कि उस पर वस्तु का स्पष्ट फ़ोकसित प्रतिबिंब प्राप्त किया जा सके? प्रतिबिंब का साइज़ तथा प्रकृति ज्ञात कीजिए।",
               "7.0 cm કદની એક વસ્તુ 18 cm કેન્દ્રલંબાઈના અંતર્ગોળ અરીસાની સામે 27 cm અંતરે મૂકી છે. અરીસાથી કેટલા અંતરે પડદો મૂકવો કે જેથી તેના પર વસ્તુનું સ્પષ્ટ પ્રતિબિંબ મળે? પ્રતિબિંબનું કદ અને પ્રકાર શોધો."),
    {1: SO, 2: ("परदा दर्पण के सामने 54 cm पर रखना चाहिए।", "પડદો અરીસાની સામે 54 cm અંતરે મૂકવો જોઈએ."), 4: ("प्रतिबिंब वास्तविक, उलटा और बड़ा (14 cm ऊँचा) है।", "પ્રતિબિંબ વાસ્તવિક, ઊલટું અને મોટું (14 cm ઊંચું) છે.")})
add("ex.q16", ("उस लेंस की फ़ोकस दूरी ज्ञात कीजिए जिसकी क्षमता –2.0 D है। यह किस प्रकार का लेंस है?", "–2.0 D પાવરવાળા લેન્સની કેન્દ્રલંબાઈ શોધો. આ કયા પ્રકારનો લેન્સ છે?"), {1: ("ऋणात्मक फ़ोकस दूरी: यह अवतल (अपसारी) लेंस है।", "ઋણ કેન્દ્રલંબાઈ: આ અંતર્ગોળ (અપસારી) લેન્સ છે.")})
add("ex.q17", ("कोई डॉक्टर +1.5 D क्षमता का संशोधक लेंस निर्धारित करता है। लेंस की फ़ोकस दूरी ज्ञात कीजिए। क्या निर्धारित लेंस अभिसारी है अथवा अपसारी?", "એક ડૉક્ટર +1.5 D પાવરનો સુધારક લેન્સ સૂચવે છે. લેન્સની કેન્દ્રલંબાઈ શોધો. શું સૂચવેલો લેન્સ અભિસારી છે કે અપસારી?"), {1: ("धनात्मक फ़ोकस दूरी: यह अभिसारी (उत्तल) लेंस है।", "ધન કેન્દ્રલંબાઈ: આ અભિસારી (બહિર્ગોળ) લેન્સ છે.")})

# Sample paper
mc("sqp30", ("आरव नोट्स बना रहा था और उसने वक्र सतहों से परावर्तन की अपनी समझ से ये कथन लिखे।\n\nI. अवतल दर्पण बिंब की स्थिति के अनुसार वास्तविक और आभासी दोनों प्रकार के प्रतिबिंब बना सकते हैं।\n\n"
              "II. उत्तल दर्पण बिंब की स्थिति कुछ भी हो, सदा वास्तविक, उलटे प्रतिबिंब बनाते हैं।\n\nIII. अवतल और उत्तल दोनों दर्पणों में प्रतिबिंब की स्थिति दर्पण सूत्र {0} से ज्ञात की जा सकती है, जहाँ f फ़ोकस दूरी, v प्रतिबिंब दूरी और u बिंब दूरी है।\n\n"
              "निम्न में से वह सही विकल्प चुनिए जिसमें वक्र सतहों से परावर्तन के सही कथन हों।",
              "આરવ નોંધ બનાવતો હતો અને તેણે વક્ર સપાટીઓ પરથી પરાવર્તનની પોતાની સમજથી આ વિધાનો લખ્યાં.\n\nI. અંતર્ગોળ અરીસા વસ્તુના સ્થાન પ્રમાણે વાસ્તવિક અને આભાસી બંને પ્રકારનાં પ્રતિબિંબ બનાવી શકે છે.\n\n"
              "II. બહિર્ગોળ અરીસા વસ્તુનું સ્થાન ગમે તે હોય, હંમેશાં વાસ્તવિક, ઊલટાં પ્રતિબિંબ બનાવે છે.\n\nIII. અંતર્ગોળ અને બહિર્ગોળ બંને અરીસામાં પ્રતિબિંબનું સ્થાન અરીસાના સૂત્ર {0} થી શોધી શકાય છે, જ્યાં f કેન્દ્રલંબાઈ, v પ્રતિબિંબ-અંતર અને u વસ્તુ-અંતર છે.\n\n"
              "નીચેનામાંથી એ સાચો વિકલ્પ પસંદ કરો જેમાં વક્ર સપાટીઓ પરથી પરાવર્તનનાં સાચાં વિધાનો હોય."),
   ("कथन II गलत है: उत्तल दर्पण सदा आभासी, सीधे प्रतिबिंब देता है। I और III सही हैं।", "વિધાન II ખોટું છે: બહિર્ગોળ અરીસો હંમેશાં આભાસી, સીધાં પ્રતિબિંબ આપે છે. I અને III સાચાં છે."),
   {"I and II": (("I और II", "I અને II"), ("कथन II गलत है: उत्तल दर्पण आभासी प्रतिबिंब देते हैं।", "વિધાન II ખોટું છે: બહિર્ગોળ અરીસા આભાસી પ્રતિબિંબ આપે છે.")), "I, II and III": (("I, II और III", "I, II અને III"), ("कथन II गलत है।", "વિધાન II ખોટું છે.")),
    "II and III": (("II और III", "II અને III"), ("कथन II गलत है।", "વિધાન II ખોટું છે.")), "I and III": (("I और III", "I અને III"), OK)})
add("sqp33", ("किसी प्रकाशिक यंत्र (डिब्बे के रूप में दिखाया गया) के सामने 20 cm पर एक बिंब रखा है। यंत्र से 10 cm पर, बिंब की ओर ही, एक आभासी, सीधा, छोटा प्रतिबिंब बनता है।\n\nA. प्रकाशिक यंत्र को पहचानिए।\n\nB. इस स्थिति में किस प्रकार का प्रतिबिंब बनता है?\n\nC. यंत्र की फ़ोकस दूरी की गणना कीजिए।",
              "કોઈ પ્રકાશીય સાધન (ડબ્બા તરીકે બતાવેલું) ની સામે 20 cm અંતરે એક વસ્તુ મૂકી છે. સાધનથી 10 cm અંતરે, વસ્તુની બાજુએ જ, એક આભાસી, સીધું, નાનું પ્રતિબિંબ મળે છે.\n\nA. પ્રકાશીય સાધન ઓળખો.\n\nB. આ સ્થિતિમાં કયા પ્રકારનું પ્રતિબિંબ મળે છે?\n\nC. સાધનની કેન્દ્રલંબાઈ ગણો."),
    {0: ("A. अवतल लेंस। B. आभासी प्रतिबिंब।", "A. અંતર્ગોળ લેન્સ. B. આભાસી પ્રતિબિંબ."), 1: ("C. {0} cm, {1} cm: {2}, अतः {3} cm", "C. {0} cm, {1} cm: {2}, તેથી {3} cm")})
add("sqp38", ("डिजिटल सिंगल लेंस रिफ़्लेक्स (DSLR) कैमरा फ़ोटोग्राफ़र उच्च गुणवत्ता के फ़ोटो लेने में प्रयोग करते हैं। इसके अंदर एक लेंस बिंब का प्रतिबिंब कैमरे के सेंसर पर बनाता है।\n\n"
              "(i) DSLR कैमरे में किस प्रकार का लेंस प्रयुक्त होता है? (1)\n\n(ii) सेंसर पर किस प्रकार का प्रतिबिंब बनता है? (1)\n\n"
              "(iii) एक फ़ोटोग्राफ़र किसी छोटी वस्तु का निकट से फ़ोटो लेने के लिए f = 50 mm फ़ोकस दूरी का लेंस प्रयोग कर रहा है। लेंस प्रतिबिंब को लेंस के पीछे 60 mm पर स्थित सेंसर पर बनाता है। बिंब दूरी की गणना कीजिए। "
              "अथवा एक फूल कैमरे के लेंस से 150 mm दूर है। फूल की वास्तविक ऊँचाई 80 mm है, और सेंसर पर प्रतिबिंब की ऊँचाई 20 mm है। लेंस की फ़ोकस दूरी की गणना कीजिए। (2)",
              "ડિજિટલ સિંગલ લેન્સ રિફ્લેક્સ (DSLR) કૅમેરા ફોટોગ્રાફરો ઉચ્ચ ગુણવત્તાના ફોટા પાડવા વાપરે છે. તેની અંદર એક લેન્સ વસ્તુનું પ્રતિબિંબ કૅમેરાના સેન્સર પર બનાવે છે.\n\n"
              "(i) DSLR કૅમેરામાં કયા પ્રકારનો લેન્સ વપરાય છે? (1)\n\n(ii) સેન્સર પર કયા પ્રકારનું પ્રતિબિંબ મળે છે? (1)\n\n"
              "(iii) એક ફોટોગ્રાફર કોઈ નાની વસ્તુનો નજીકથી ફોટો પાડવા f = 50 mm કેન્દ્રલંબાઈનો લેન્સ વાપરે છે. લેન્સ પ્રતિબિંબને લેન્સની પાછળ 60 mm અંતરે આવેલા સેન્સર પર બનાવે છે. વસ્તુ-અંતર ગણો. "
              "અથવા એક ફૂલ કૅમેરાના લેન્સથી 150 mm દૂર છે. ફૂલની વાસ્તવિક ઊંચાઈ 80 mm છે, અને સેન્સર પર પ્રતિબિંબની ઊંચાઈ 20 mm છે. લેન્સની કેન્દ્રલંબાઈ ગણો. (2)"),
    {0: ("(i) उत्तल लेंस।", "(i) બહિર્ગોળ લેન્સ."), 1: ("(ii) वास्तविक और उलटा।", "(ii) વાસ્તવિક અને ઊલટું."),
     2: ("(iii) {0} mm, {1} mm: {2}, अतः {3} mm: बिंब लेंस के सामने 300 mm पर है।", "(iii) {0} mm, {1} mm: {2}, તેથી {3} mm: વસ્તુ લેન્સની સામે 300 mm અંતરે છે."),
     3: ("अथवा {0}; {1} mm; {2}, अतः {3} mm।", "અથવા {0}; {1} mm; {2}, તેથી {3} mm.")})

